begin;
select no_plan();
select has_table('public','stock_events','livro de estoque existe');
select has_function('public','record_stock_event',array['jsonb','uuid'],'RPC de estoque existe');
insert into auth.users(id) values('61000000-0000-0000-0000-000000000001'),('61000000-0000-0000-0000-000000000002'),('61000000-0000-0000-0000-000000000003');
insert into public.profiles values('61000000-0000-0000-0000-000000000001','owner'),('61000000-0000-0000-0000-000000000002','driver'),('61000000-0000-0000-0000-000000000003','driver');
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000001',true);
set local role authenticated;
savepoint initial_fixture;
select is(public.record_stock_event('{"kind":"opening","location":"farm","eggs":2,"effectiveAt":"2026-09-01T12:00:00Z"}',gen_random_uuid())->>'costCents',null::text,'abertura sem custo permanece desconhecida');
select is((select count(*) from public.expenses),0::bigint,'abertura não gera despesa');
select is((select eggs from public.stock_balances where location='farm'),2,'abertura registra ovos');
rollback to initial_fixture;
select is(public.record_stock_event('{"kind":"purchase","location":"farm","eggs":300,"costCents":30000,"effectiveAt":"2026-10-01T12:00:00Z"}','62000000-0000-0000-0000-000000000001')->>'costCents','30000','compra retorna custo integral');
select is(public.record_stock_event('{"kind":"purchase","location":"farm","eggs":300,"costCents":30000,"effectiveAt":"2026-10-01T12:00:00Z"}','62000000-0000-0000-0000-000000000001')->>'eggs','300','repetição preserva resposta');
select is((select count(*) from public.stock_events),1::bigint,'replay não duplica entrada');
select is((select amount_cents from public.expenses),30000::bigint,'compra gera despesa na transação');
select throws_ok($$select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":301,"costCents":30000,"effectiveAt":"2026-10-01T12:00:00Z"}','62000000-0000-0000-0000-000000000001')$$,'22023','Request conflict','payload diferente rejeitado');
select throws_ok($$select public.record_stock_event('{"kind":"opening","location":"farm","eggs":10,"effectiveAt":"2026-10-02T12:00:00Z"}',gen_random_uuid())$$,'PT409','OPENING_LOCKED','abertura posterior não substitui saldo');
select throws_ok($$select public.record_stock_event('{"kind":"loss","location":"farm","eggs":301,"reason":"Quebra","effectiveAt":"2026-10-02T12:00:00Z"}',gen_random_uuid())$$,'22023','INSUFFICIENT_STOCK','saldo negativo bloqueado');
select throws_ok($$select public.record_stock_event('{"kind":"adjustment","direction":"in","location":"farm","eggs":1,"effectiveAt":"2026-10-02T12:00:00Z"}',gen_random_uuid())$$,'22023','REASON_REQUIRED','ajuste exige motivo');
select throws_ok($$select public.record_stock_event('{"kind":"purchase","location":"vehicle","eggs":1,"costCents":1,"effectiveAt":"2026-10-02T12:00:00Z"}',gen_random_uuid())$$,'22023','INVALID_INPUT','genérica não movimenta veículo');
select throws_ok($$update public.stock_balances set eggs=0$$,'42501',null,'escrita direta do saldo negada');
select throws_ok($$delete from public.stock_events$$,'42501',null,'histórico não apagável');
reset role;
insert into public.vehicles(id,name) values('63000000-0000-0000-0000-000000000001','Veículo fictício estoque');
insert into public.route_runs(id,template_id,service_date,driver_id,vehicle_id) values('64000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000002','2034-01-03','61000000-0000-0000-0000-000000000002','63000000-0000-0000-0000-000000000001'),('64000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','2034-01-10','61000000-0000-0000-0000-000000000003','63000000-0000-0000-0000-000000000001');
-- Private fixtures model future delivery/reconciliation, never public bypass RPCs.
select private.transfer_stock('64000000-0000-0000-0000-000000000001','load',300,'65000000-0000-0000-0000-000000000001');
select is((select total_cost_cents from public.stock_balances where location='vehicle'),30000::bigint,'carga transfere valor integral');
select private.transfer_stock('64000000-0000-0000-0000-000000000001','load',300,'65000000-0000-0000-0000-000000000001');
select is((select eggs from public.stock_balances where location='vehicle'),300,'replay da carga não duplica');
set local role authenticated;
select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":300,"costCents":60000,"effectiveAt":"2098-01-01T12:00:00Z"}',gen_random_uuid());
reset role;
select throws_ok($$select private.transfer_stock('64000000-0000-0000-0000-000000000002','load',1,gen_random_uuid())$$,'PT409','VEHICLE_ALREADY_LOADED','único veículo não aceita segunda carga');
select private.consume_stock('64000000-0000-0000-0000-000000000001','sale',240,gen_random_uuid());
select private.consume_stock('64000000-0000-0000-0000-000000000001','loss',10,gen_random_uuid());
select private.transfer_stock('64000000-0000-0000-0000-000000000001','return',50,'65000000-0000-0000-0000-000000000002');
select is((select eggs from public.stock_balances where location='vehicle'),0,'240 entregues + 50 retorno + 10 perdas fecha carga');
select is((select total_cost_cents from public.stock_balances where location='farm'),65000::bigint,'retorno usa custo da carga e não compra nova');
select is((select total_cost_cents from public.stock_balances where location='vehicle'),0::bigint,'esvaziamento não deixa custo residual');
set local role authenticated;
select throws_ok($$select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":1,"costCents":1,"effectiveAt":"2026-09-01T12:00:00Z"}',gen_random_uuid())$$,'PT409','BACKDATED_STOCK','compra retroativa não altera custos apropriados');
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.record_stock_event('{"kind":"adjustment","location":"farm","direction":"out","eggs":1,"reason":"teste","effectiveAt":"2099-01-01T12:00:00Z"}',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não ajusta');
select is((select count(*) from public.stock_events),0::bigint,'motorista não lê custos do livro');
select is((select count(*) from public.stock_balances),0::bigint,'motorista não lê custos do saldo');
select is(public.get_my_stock()->>'eggs','0','motorista lê só ovos da própria carga');
select ok(not(public.get_my_stock() ? 'costCents'),'projeção não contém custo');
select throws_ok($$select private.transfer_stock('64000000-0000-0000-0000-000000000001','return',1,gen_random_uuid())$$,'42501',null,'helper privado inacessível');
select throws_ok($$select public.set_remaining_stock_cost('farm',1,'teste',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não regulariza');
reset role;
-- Empty farm through a current loss, then start an unknown-cost balance.
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000001',true);
select private.consume_stock(null,'loss',350,gen_random_uuid());
set local role authenticated;
select public.record_stock_event('{"kind":"adjustment","direction":"in","location":"farm","eggs":3,"reason":"Contagem fictícia","effectiveAt":"2099-01-01T12:00:00Z"}',gen_random_uuid());
select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":3,"costCents":100,"effectiveAt":"2099-01-02T12:00:00Z"}',gen_random_uuid());
select is((select total_cost_cents from public.stock_balances where location='farm'),null::bigint,'compra nova não apaga custo desconhecido');
reset role;
select private.consume_stock(null,'sale',3,'66000000-0000-0000-0000-000000000001');
set local role authenticated;
select public.set_remaining_stock_cost('farm',100,'Custo contado fictício','67000000-0000-0000-0000-000000000001');
select public.set_remaining_stock_cost('farm',100,'Custo contado fictício','67000000-0000-0000-0000-000000000001');
select is((select count(*) from public.stock_events where kind='cost_regularization'),1::bigint,'regularização idempotente');
select is((select eggs from public.stock_balances where location='farm'),3,'regularização não altera ovos');
select is((select count(*) from public.expenses),3::bigint,'regularização não gera caixa');
select is((select cost_cents from public.stock_events where source_event_id='66000000-0000-0000-0000-000000000001'),null::bigint,'venda anterior permanece custo desconhecido');
reset role;
select private.consume_stock(null,'sale',1,gen_random_uuid());
select private.consume_stock(null,'sale',1,gen_random_uuid());
select private.consume_stock(null,'sale',1,gen_random_uuid());
select is((select total_cost_cents from public.stock_balances where location='farm'),0::bigint,'100/3 esvazia sem sobra monetária');
select is((select sum(cost_cents) from (select cost_cents from public.stock_events where kind='sale' and cost_cents is not null order by created_at desc,id desc limit 3)s),100::numeric,'saídas somam exatamente custo regularizado');
set local role authenticated;
select is(public.reconcile_stock_request('68000000-0000-0000-0000-000000000001')->>'status','closed','reconciliação encerra intenção ausente');
select throws_ok($$select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":1,"costCents":1,"effectiveAt":"2100-01-01T12:00:00Z"}','68000000-0000-0000-0000-000000000001')$$,'55000','REQUEST_CLOSED','request encerrado nunca executa compra atrasada');
select is(public.reconcile_stock_request('62000000-0000-0000-0000-000000000001')->>'status','saved','reconciliação recupera compra salva');
select is(public.reconcile_stock_request('67000000-0000-0000-0000-000000000001','set_remaining_stock_cost')->>'status','saved','reconciliação recupera regularização');
select throws_ok($$select public.record_stock_event('{"kind":"opening","location":"farm","eggs":1,"costCents":9007199254740992,"effectiveAt":"2100-01-01T12:00:00Z"}',gen_random_uuid())$$,'22003','AMOUNT_OUT_OF_RANGE','valor acima de inteiro seguro negado');
select public.record_stock_event('{"kind":"adjustment","location":"farm","direction":"in","eggs":1,"reason":"Sem custo fictício","effectiveAt":"2100-01-01T12:00:00Z"}',gen_random_uuid());
select public.record_stock_event('{"kind":"loss","location":"farm","eggs":1,"reason":"Esvaziar fictício","effectiveAt":"2100-01-02T12:00:00Z"}',gen_random_uuid());
select is((select total_cost_cents from public.stock_balances where location='farm'),0::bigint,'esvaziar custo desconhecido restaura zero físico');
select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":1,"costCents":12,"effectiveAt":"2100-01-03T12:00:00Z"}',gen_random_uuid());
select is((select total_cost_cents from public.stock_balances where location='farm'),12::bigint,'nova compra após esvaziamento conhece custo');
reset role;
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.reconcile_stock_request('62000000-0000-0000-0000-000000000001')$$,'42501','FORBIDDEN','motorista não reconcilia compra');
reset role;
set local role anon;
select throws_ok($$select public.record_stock_event('{}',gen_random_uuid())$$,'42501',null,'anônimo não registra estoque');
select throws_ok($$select public.set_remaining_stock_cost('farm',12,'teste',gen_random_uuid())$$,'42501',null,'anônimo não regulariza');
select throws_ok($$select * from public.stock_events$$,'42501',null,'anônimo não lê livro');
reset role;
select * from finish();
rollback;
